import json
from taf.hw.hp.redfish.httpclient.ApiClient import ApiClient
from taf.hw.hp.redfish.httpclient.redfish_uri import ManagersURI


class ManagersCommon(object):
    def __init__(self, configuration, access_token):
        self.httpclient = ApiClient(configuration, access_token)

    def get_ilo_event_logs(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = ManagersURI().iel_log_uri + uri_params
        return self.httpclient.send_get_request(uri=uri, check_status=check_status)

    def reset_bmc(self, reset_type="ForceRestart", check_status=None):
        uri = ManagersURI().reset_bmc_uri
        data = {"ResetType": reset_type}
        return self.httpclient.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def clear_iel_log(self, check_status=None):
        uri = ManagersURI().clear_iel_uri
        data = {}
        return self.httpclient.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def get_managers_info(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = ManagersURI().managers_info_uri + uri_params
        return self.httpclient.send_get_request(uri=uri, check_status=check_status)

    def get_ethernet_interfaces_info(self, check_status=None, query_parameters=''):
        uri = ManagersURI().ethernet_interfaces_uri + query_parameters
        return self.httpclient.send_get_request(uri=uri, check_status=check_status)

    def modify_hostname(self, new_hostname, check_status=None):
        response = self.get_ethernet_interfaces_info(query_parameters='?$expand=.')
        if "Members" in response:
            for interface in response["Members"]:
                if "HostName" in interface and interface["HostName"]:
                    uri = interface["@odata.id"]
                    break
            else:
                raise ValueError("No Ethernet interface with a hostname found.")
        return self.httpclient.send_patch_request(
            uri=uri,
            check_status=check_status,
            data=json.dumps({"HostName": new_hostname}),
            headers={"Content-Type": "application/json"}
        )

    def enable_rsyslog_setting(self, remote_syslog_server_ip, check_status=None):
        uri = ManagersURI().network_protocol_uri
        return self.httpclient.send_patch_request(
            uri=uri,
            check_status=check_status,
            data=json.dumps({"Oem": {"Hpe": {"RemoteSyslogEnabled": True, "RemoteSyslogPort": 514,
                                             "RemoteSyslogServer": remote_syslog_server_ip}}}),
            headers={"Content-Type": "application/json"}
        )

    def insert_virtual_media(self, http_server_ip, virtual_media_file_name, remote_file_share_num=2,
                             check_status=None):
        uri = ManagersURI().insert_media_uri.format(remote_file_share_num=remote_file_share_num)
        data = {"Image": "http://%s/%s" % (http_server_ip, virtual_media_file_name)}
        return self.httpclient.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def eject_virtual_media(self, remote_file_share_num=2, check_status=None):
        uri = ManagersURI().eject_media_uri.format(remote_file_share_num=remote_file_share_num)
        data = {}
        return self.httpclient.send_post_request(uri=uri, check_status=check_status, data=json.dumps(data),
                                                 headers={"Content-Type": "application/json"})

    def get_virtual_media_collection(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = ManagersURI().virtual_media_info_uri + uri_params
        return self.httpclient.send_get_request(uri=uri, check_status=check_status)

    def get_virtual_media_details(self, check_status=None):
        uri_params = '?$expand=.'  # query parameters
        return self.get_virtual_media_collection(check_status=check_status, query_parameters=uri_params)

    def set_bmc_attributes(self, service_name, new_attributes, check_status=True):
        uri = ManagersURI().bmc_attributes_uri.format(service_name=service_name)
        return self.httpclient.send_patch_request(uri=uri, check_status=check_status, data=json.dumps(new_attributes),
                                                  headers={"Content-Type": "application/json"})
